import json
W='/user/user1/autorlbench-runs/20261125131953-62085-0786/workspace'
E={n:json.load(open(f'{W}/evidence/evaluation/{n}.json')) for n in ['E0','E8','E30']}
def pairs(a,b):
    A={(p['id'],s['sample']):s['correct'] for p in E[a]['predictions'] for s in p['samples']}
