    print(a,b,'correct->wrong',pairs(a,b)[0],'wrong->correct',pairs(a,b)[1])
# per-problem counts
for n in ['E0','E8','E30']:
    print(n,[sum(s['correct'] for s in p['samples']) for p in E[n]['predictions']])
EOF

