import re,glob
W='/user/user1/autorlbench-runs/20261125131953-62085-0786/workspace'
allrows={}
for path in [f'{W}/evidence/training/steps-01-08/train.stdout',f'{W}/evidence/training/steps-09-30/train.stdout']:
    for l in open(path,errors='replace'):
        l=re.sub(r'\x1b\[[0-9;]*m','',l)
        m=re.search(r'\bstep:(\d+) - (.*)$',l)
        if not m: continue
        st=int(m.group(1)); d={}
        for part in m.group(2).split(' - '):
            if ':' in part:
                k,v=part.rsplit(':',1)
                try: d[k]=float(v)
                except: pass
        allrows[st]=d
keys=sorted(set().union(*[set(d) for d in allrows.values()]))
print('num steps',len(allrows),'num metrics',len(keys))
# print selected metrics
sel=['critic/score/mean','critic/rewards/mean','actor/pg_loss','actor/grad_norm','actor/entropy','actor/lr','actor/ppo_kl','actor/pg_clipfrac','actor/block_align_loss','response_length/mean','response_length/clip_ratio','response_length/max','qat/rollout_logprob_mae','qat/rollout_logprob_bias','qat/rollout_logprob_corr','qat/rollout_logprob_frac_gt_0p1','rollout_corr/training_ppl','rollout_corr/rollout_ppl','timing_s/step','timing_s/gen','timing_s/adv','timing_s/update_actor']
for k in sel:
    vals=[allrows[s].get(k) for s in sorted(allrows)]
    print(f'{k:45s}', ' '.join(f'{v:.4g}' if v is not None else 'NA' for v in vals))
print()
print('all metric keys containing entropy/reward/score/acc/kl:')
for k in keys:
    if any(x in k.lower() for x in ['entropy','reward','score','acc','kl','grad','loss']):
        pass
print([k for k in keys if 'entropy' in k])
print([k for k in keys if 'reward' in k or 'score' in k or 'acc' in k][:40])
